<template><view class="page"><view class="back" @tap="back">‹</view><image v-if="product.image" class="product-image" :src="product.image" mode="aspectFill"/><view v-else class="product-image">◇</view><view class="card info"><text class="product-title">{{product.name}}</text><text class="label">商品碳标签：{{product.carbonLabel||'绿色权益'}}</text><text class="carbon">预计减碳：{{product.carbonReduction||0}} kg CO₂/件</text><text class="price">{{product.points}} 积分</text><text class="desc">{{product.description||'环保商品，兑换后请联系企业领取。'}}</text><text class="muted">当前库存：{{product.stock}}</text></view><view class="primary-btn submit" @tap="exchange">立即兑换</view></view></template>
<script>import {callCloud} from '../../common/cloud.js';import {toast} from '../../common/mock.js';export default{data(){return{product:{},id:''}},async onLoad(options){this.id=options.id;try{const result=await callCloud('product-list');this.product=(result.data||[]).find(x=>x._id===this.id)||{};const userId=uni.getStorageSync('user_session')?.id;if(userId&&this.product.enterpriseId)await callCloud('product-view',{productId:this.id,userId,enterpriseId:this.product.enterpriseId})}catch(error){}},methods:{back(){uni.navigateBack()},async exchange(){const userId=uni.getStorageSync('user_session')?.id;if(!userId)return toast('请先登录');try{const result=await callCloud('product-exchange',{productId:this.id,userId});uni.setStorageSync('user_points',result.points);toast('兑换成功，积分已扣除');setTimeout(()=>uni.navigateBack(),500)}catch(error){toast(error.message||'兑换失败')}}}}</script>
<style lang="scss">@import '../../common/portal.scss';.back{font-size:58rpx}.product-image{width:100%;height:420rpx;border-radius:28rpx;background:#d6e6e3;color:#006d37;font-size:130rpx}.info{margin-top:24rpx}.product-title{display:block;font-size:38rpx;font-weight:700}.label,.carbon,.desc{display:block;margin-top:18rpx}.carbon{color:#347c55}.price{display:block;margin:24rpx 0;color:#006d37;font-size:38rpx;font-weight:700}.desc{color:#53615f;line-height:1.7}.submit{margin-top:34rpx}</style>
